def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    # Check if it's a doubled quote
                    if i + 1 < len(line) and line[i + 1] == '"':
                        field += '"'
                        i += 2
                    else:
                        # End of quoted field
                        i += 1
                        # Check what follows
                        if i < len(line):
                            if line[i] == ',':
                                i += 1
                            else:
                                return None
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Unterminated quoted field
                return None
            fields.append(field)
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields

